class Solution { fun findHighAccessEmployees(access_times:List<List<String>>):List<String>{val times=java.util.TreeMap<String,MutableList<Int>>();for(access in access_times){val value=access[1];val minute=value.substring(0,2).toInt()*60+value.substring(2).toInt();times.getOrPut(access[0]){mutableListOf()}.add(minute)};val answer=mutableListOf<String>();for((name,values) in times){values.sort();for(i in 2 until values.size)if(values[i]-values[i-2]<60){answer.add(name);break}};return answer} }
